import {GYMS,RIVALS,SHOP,createState,sanitizeState,power,nextRival,train,rest,work,buy,beginFight,fightTurn} from './engine.mjs';

const $=id=>document.getElementById(id);
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SAVE_KEY='gymboss:iron-king:v1';
const stats={strength:'Сила',technique:'Техника',endurance:'Выносливость'};
const exercises={strength:{name:'Жим лёжа',icon:'↥',call:'ЖМИ. НЕ ДУМАЙ.',cue:'Выжимай, когда маркер в зелёной зоне.'},technique:{name:'Школа захвата',icon:'⌁',call:'МЯГКО СТЕЛЕШЬ.',cue:'Лови момент. Техника сильнее понтов.'},endurance:{name:'День ног',icon:'↟',call:'НОГИ ТОЖЕ ЛЮДИ.',cue:'Держи ритм. Лестница завтра тебя вспомнит.'}};
const ranks=[{name:'ПОКА ЕЩЁ<br>ДРИЩ',desc:'Гриф тяжелее твоих аргументов.',headline:'ТВОЙ ПЕРВЫЙ<br><em>ПОДХОД.</em>',quote:'«В этом зале тебя пока зовут “эй”.»'},{name:'УЖЕ<br>НЕ СМЕШНО',desc:'Футболка начала задавать вопросы.',headline:'МАССА ЕСТЬ.<br><em>ВОПРОСЫ?</em>',quote:'«Бро, ты случайно не стал шире двери?»'},{name:'ЖИВАЯ<br>МАШИНА',desc:'Штанга просит тебя о страховке.',headline:'СВЯТОЙ<br><em>ПАМП.</em>',quote:'«Твои трапеции видны из космоса.»'},{name:'БОЛЬШОЙ<br>МАЛЬЧИК',desc:'Сила есть. Осталось забрать трон.',headline:'BOSS OF<br><em>THIS GYM.</em>',quote:'«Ты не занимаешь место. Ты его создаёшь.»'}];
const achievements=[['first-workout','Первый памп','Завершить первую тренировку'],['first-win','Коврик теперь твой','Победить первого соперника'],['first-gear','Приоделся, красавчик','Купить экипировку'],['gym-two','Вырос из подвала','Открыть второй зал'],['legend','BOSS OF THIS GYM','Забрать все 12 побед']];
const coachLines=['Штанга сама себя не поднимет. Хотя тебя, может, и поднимет.','Кто пропускает день ног, тот пропускает жизнь.','Три сотни баксов? У нас пока тридцать пять рублей.','Два подхода назад ты был другим человеком.','Правило зала: блины после себя убери. Эго можешь оставить.','Пот — это слёзы твоей лени. Вытри скамейку.','Ну что, fucking strong или пока just fucking tired?'];
const position=p=>`${p%2===0?'0%':'100%'} ${p<2?'0%':'100%'}`;
const heroStage=s=>s.won?3:Math.min(3,Math.max(s.gym,Math.floor(s.workouts/15)));
const heroPath=s=>`./assets/hero-${heroStage(s)}.png?v=fullbody`;
let state=createState(),battle=null,tab='gym',sound=false,audio=null,modalKind=null,cleanup=null,working=false,saveFailed=false,tickFrame=0,roundLock=false,saved=false;
try{const raw=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');if(raw?.state){state=sanitizeState(raw.state);saved=true;sound=!!raw.sound;const b=raw.battle;if(b&&!b.finished&&b.rivalId===nextRival(state)?.id&&['push','counter','grip'].includes(b.telegraph)&&[b.playerHp,b.enemyHp,b.playerStamina,b.round,b.playerPower].every(Number.isFinite)&&b.playerHp>0&&b.playerHp<=100&&b.enemyHp>0&&b.enemyHp<=100&&b.playerStamina>=0&&b.playerStamina<=100&&Number.isInteger(b.round)&&b.round>=0&&b.round<10&&b.playerPower>0&&b.playerPower<=1000&&Array.isArray(b.history)){battle={...b,finished:false,result:null,history:b.history.slice(-10)};}}}catch{saved=false;}

function persist(){try{localStorage.setItem(SAVE_KEY,JSON.stringify({state,battle:battle&&!battle.finished?battle:null,sound}));saveFailed=false;}catch{saveFailed=true;}const el=$('save-status');if(el){el.textContent=saveFailed?'Сохранение недоступно в этом браузере':'Прогресс сохранён в этом браузере';el.classList.toggle('save-warning',saveFailed);}}
function tone(kind='tap'){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')void audio.resume();const freqs=kind==='win'?[220,330,440,660]:kind==='perfect'?[440,660]:kind==='hit'?[85,55]:kind==='error'?[160,120]:[260];freqs.forEach((f,i)=>{const osc=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.085;osc.type=kind==='hit'?'triangle':'sine';osc.frequency.setValueAtTime(f,t);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.055,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+.17);osc.connect(g);g.connect(audio.destination);osc.start(t);osc.stop(t+.2);});}catch{sound=false;}}
function toast(message,error=false){const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=message;$('toasts').append(el);setTimeout(()=>el.remove(),4400);if(error)tone('error');}
function apply(result,{quiet=false}={}){if(result.error){toast(result.error,true);return false;}const oldAchievements=new Set(state.achievements);state=result.state;persist();render();if(!quiet&&result.message)toast(result.message);for(const id of state.achievements){if(!oldAchievements.has(id)){const a=achievements.find(x=>x[0]===id);setTimeout(()=>toast(`Достижение: ${a?.[1]??id}`),500);}}return true;}
function gainsPop(gains){const el=$('floating-gains');el.innerHTML=Object.entries(gains).filter(([,v])=>v>0).map(([k,v])=>`+${v} ${stats[k].toLowerCase()}`).join('<br>');el.classList.remove('gain-pop');void el.offsetWidth;el.classList.add('gain-pop');}

function gymMarkup(){return `<div class="training-heading"><h2>ВЫБЕРИ ТРЕНИРОВКУ</h2></div><div class="training-list">${Object.entries(exercises).map(([k,e])=>`<button class="training-card" data-train="${k}" ${state.energy<18?'disabled':''}><span class="exercise-icon" aria-hidden="true">${e.icon}</span><span><strong>${e.name}</strong><small>${{strength:'Сила',technique:'Техника',endurance:'Выносливость'}[k]}</small></span><span class="action-price">18 ⚡</span></button>`).join('')}</div><div class="support-group"><span class="group-title">МЕЖДУ ПОДХОДАМИ</span><div class="utility-actions"><button id="rest-button" ${state.energy===100?'disabled':''}><span aria-hidden="true">☾</span><strong>Отдых</strong><small>+40 энергии · 6 сек.</small></button><button id="work-button" ${state.energy<12?'disabled':''}><span aria-hidden="true">₽</span><strong>Подработка</strong><small>+${35+state.gym*15} ₽ · −12 энергии</small></button></div></div>`;}
function fightMarkup(){const rival=nextRival(state);if(!rival)return `<div class="fight-panel"><span class="group-title">ФИНАЛ</span><h2>ТРЕНАЖЁРЫ ТЕПЕРЬ СЛУШАЮТСЯ ТЕБЯ.</h2><p class="dialog-copy">Все 12 соперников побеждены. Трон твой.</p><button id="victory-button" class="primary-button">МОЙ ТРИУМФ <span>♛</span></button></div>`;const ratio=power(state)/rival.power;return `<div class="fight-panel"><div class="section-heading"><span class="group-title">СОПЕРНИК ${String(state.wins+1).padStart(2,'0')} / 12</span><span class="fight-stage-label">${state.wins%3===2?'БОСС ЗАЛА':GYMS[state.gym].name.toUpperCase()}</span></div><div class="featured-rival"><div class="rival-portrait" style="background-position:${position(rival.portrait)}" role="img" aria-label="${esc(rival.name)}"></div><div><span class="tiny-label">${esc(rival.title)}</span><h2>${esc(rival.name)}</h2><p>«${esc(rival.quote)}»</p></div></div><div class="fight-readiness"><div><span>ТВОЯ МОЩЬ</span><strong>${power(state)}</strong></div><span class="readiness-vs">VS</span><div><span>ЕГО МОЩЬ</span><strong>${rival.power}</strong></div></div><p class="readiness-hint">${ratio>=.87?'Ты готов. Читай его движения и забирай победу.':ratio>=.77?'Победа возможна, если точно отвечать на приёмы.':'Сначала подкачайся, тогда схватка будет честнее.'}</p><button class="primary-button" id="fight-button" ${state.energy<20?'disabled':''}>ВЫЙТИ НА КОВЁР <span>↗</span></button><div class="fight-footnote"><span>Нужно 20 энергии</span><span>Награда: ${rival.reward} ₽</span></div></div>`;}
function shopMarkup(){const equipped=state.equipment.map(id=>SHOP.find(item=>item.id===id)?.name).filter(Boolean);if(state.buff)equipped.push(`${SHOP.find(item=>item.id===state.buff.id)?.name} ×${state.buff.charges}`);const itemMarkup=item=>{const owned=state.equipment.includes(item.id);const disabled=owned||state.money<item.cost||(item.type==='boost'&&state.buff)||(item.type==='food'&&state.energy===100);return `<article class="shop-item"><div><h3>${esc(item.name)}</h3><p>${esc(item.description)}</p><span class="shop-effect">${esc(item.effect)}</span></div><button class="shop-buy" data-buy="${item.id}" ${disabled?'disabled':''}>${owned?'КУПЛЕНО':item.type==='boost'&&state.buff?'БУСТ АКТИВЕН':`${item.cost} ₽`}</button></article>`;};const groups=[['Перекус',SHOP.filter(item=>item.type==='food')],['Усилители',SHOP.filter(item=>item.type==='boost')],['Экипировка',SHOP.filter(item=>item.type==='gear')]];return `<div class="training-heading"><h2>ЛАВКА</h2></div>${equipped.length?`<p class="loadout">Сейчас на тебе: ${esc(equipped.join(' · '))}</p>`:''}${groups.map(([title,items])=>`<section class="shop-group"><h3 class="shop-group-title">${title}</h3><div class="shop-list">${items.map(itemMarkup).join('')}</div></section>`).join('')}`;}
function roadMarkup(){return `<div class="training-heading"><h2>ПУТЬ К ТРОНУ</h2></div><div class="gym-panorama" style="background-position:${position(state.gym)}" role="img" aria-label="${esc(GYMS[state.gym].name)}"></div><p class="muted" style="margin:15px 0">${esc(GYMS[state.gym].description)}</p>${GYMS.map((gym,index)=>{const wins=Math.max(0,Math.min(3,state.wins-index*3));return `<details class="road-group" ${index===state.gym?'open':''}><summary><strong>${index+1}. ${esc(gym.name)}</strong><span>${index>state.gym?'Закрыто':`${wins} / 3 победы`}</span></summary>${RIVALS.filter(r=>r.gym===index).map(r=>{const i=RIVALS.indexOf(r);return `<div class="road-item"><div class="rival-portrait" style="background-position:${position(r.portrait)}"></div><div><h3>${esc(r.name)}</h3><p>Мощь ${r.power} · ${esc(r.title)}</p></div><span class="road-state">${i<state.wins?'✓':i===state.wins?'ТВОЙ ХОД':'—'}</span></div>`;}).join('')}</details>`;}).join('')}`;}
function render(){const stage=heroStage(state),rank=ranks[stage],rival=nextRival(state);$('chapter-label').textContent=`ГЛАВА ${String(state.gym+1).padStart(2,'0')} / 04`;$('gym-name').textContent=state.won?'Твоя империя железа':state.gym===0?'Подвал потных надежд':GYMS[state.gym].name;$('money').innerHTML=`${state.money.toLocaleString('ru-RU')} <span>₽</span>`;$('respect').innerHTML=`${state.respect} <span>REP</span>`;$('player-rank').textContent=state.won?'БОСС КАЧАЛКИ':rank.name.replace('<br>',' ');$('rank-description').textContent=state.won?'Ты пришёл. Поднял. Возглавил.':rank.desc;$('power-value').textContent=power(state);$('power-next').textContent=rival?`/ ${rival.power} у соперника`:'/ ЛЕГЕНДА';$('stats').innerHTML=Object.keys(stats).map(k=>`<div class="stat"><div><span>${stats[k]}</span><strong>${state[k]}</strong></div><div class="stat-track"><i style="width:${Math.min(100,state[k])}%"></i></div></div>`).join('');$('energy-value').textContent=`${state.energy} / 100`;$('energy-bar').style.width=`${state.energy}%`;$('energy-bar').style.background=state.energy<20?'var(--orange)':'var(--cyan)';$('energy-hint').textContent=state.energy<20?'Без сил? Отдых бесплатный. Батя разрешил.':state.energy<50?'Ещё подход — и пора на скамейку.':'Полон сил. Почти как настоящий качок.';const equipped=state.equipment.map(id=>SHOP.find(i=>i.id===id)?.name).filter(Boolean);if(state.buff)equipped.push(`${SHOP.find(i=>i.id===state.buff.id)?.name} ×${state.buff.charges}`);$('equipment').textContent=equipped.length?equipped.join(' · '):'Потёртые шорты. Чистая вера.';$('achievement-count').textContent=`${state.achievements.length} / ${achievements.length}`;const hero=$('hero-image');if(!hero.src.endsWith(`hero-${stage}.png?v=fullbody`)){hero.src=heroPath(state);if(!matchMedia('(prefers-reduced-motion: reduce)').matches)hero.animate([{opacity:.3},{opacity:1}],{duration:700});}hero.alt=['Худой новичок в качалке','Подтянутый атлет','Огромный мускулистый спортсмен','Гипертрофированный чемпион качалки'][stage];$('hero-name').innerHTML=state.won?'ТЫ — БОСС.<br><em>БЕЗ БАЗАРА.</em>':rank.headline;$('hero-quote').textContent=rank.quote;$('evolution-strip').innerHTML=['ДРИЩ','АТЛЕТ','МАШИНА','БОСС'].map((name,i)=>`${i?'<i></i>':''}<span class="${i<=stage?'active':''}">${name}</span>`).join('');$('action-content').innerHTML=tab==='gym'?gymMarkup():tab==='fight'?fightMarkup():tab==='shop'?shopMarkup():roadMarkup();$('action-content').setAttribute('aria-labelledby',`tab-${tab}`);document.querySelectorAll('[data-tab]').forEach(el=>{const active=el.dataset.tab===tab;el.classList.toggle('active',active);el.setAttribute('aria-selected',String(active));el.tabIndex=active?0:-1;});$('campaign-strip').innerHTML=`<div class="campaign-progress"><span>ПУТЬ К ТРОНУ</span><div class="campaign-track"><i style="width:${state.wins/12*100}%"></i></div><strong>${state.wins} / 12 побед</strong></div><div class="campaign-names">${GYMS.map((g,i)=>`<span class="${i===state.gym?'current':i<state.gym?'done':''}">${i<state.gym?'✓ ':''}${esc(g.name)}</span>`).join('')}</div>`;$('log-line').innerHTML=`<span>ТРЕНЕР</span> ${esc(state.log.at(-1)||coachLines[0])}`;$('sound-toggle').classList.toggle('enabled',sound);$('sound-toggle').setAttribute('aria-label',sound?'Выключить звук':'Включить звук');$('sound-toggle').textContent=sound?'♫':'♪';}

function closeModal(){if(modalKind==='fight'&&battle&&!battle.finished){toast('Заверши схватку или нажми «Сдаться».');return;}cleanup?.();cleanup=null;modalKind=null;working=false;$('game-dialog').close();document.querySelector('.arena-scene').classList.remove('scene-training');}
function modal(html,kind='info'){cleanup?.();cleanup=null;modalKind=kind;$('dialog-content').innerHTML=html;if(!$('game-dialog').open)$('game-dialog').showModal();}
function modalTop(eyebrow,closable=true){return `<div class="dialog-top"><span class="tiny-label">${eyebrow}</span>${closable?'<button class="close-button" data-close aria-label="Закрыть">×</button>':''}</div>`;}
function help(){modal(`<div class="dialog-body">${modalTop('ПРАВИЛА ПОДВАЛА')}<h2 id="dialog-title">СЛУШАЙ СЮДА, НОВЕНЬКИЙ.</h2><ol class="help-list"><li><strong>Качайся.</strong> В каждом подходе 6 повторений. Жми кнопку или пробел, когда бегунок в зелёной зоне. Точность даёт больше роста.</li><li><strong>Восстанавливайся.</strong> Отдых бесплатный. На шаурму и экипировку заработай подработкой или победами.</li><li><strong>Читай соперника.</strong> Контрприём побеждает натиск, захват — контрприём, натиск — захват. Попади в ритм для большего урона.</li><li><strong>Не пропускай день ног.</strong> Прокачивай все три навыка. Ориентир перед боем — хотя бы 87% мощи соперника.</li><li><strong>Забери трон.</strong> Четыре зала, 12 соперников, финальный Гигабатя. Прохождение рассчитано примерно на 20–30 минут.</li></ol><p class="dialog-copy">Прогресс автоматически остаётся в этом браузере. Звук включается кнопкой ♪. Схватку можно продолжить после перезагрузки.</p><button class="primary-button" data-close>ПОНЯЛ. ПОШЁЛ КАЧАТЬСЯ. <span>↗</span></button></div>`);}
function showAchievements(){modal(`<div class="dialog-body">${modalTop('ТВОЙ ШКАФ С КУБКАМИ')}<h2 id="dialog-title">ЗАСЛУГИ ПЕРЕД ЖЕЛЕЗОМ.</h2><div class="achievement-list">${achievements.map(([id,name,desc])=>`<div class="achievement-item ${state.achievements.includes(id)?'':'locked'}">${state.achievements.includes(id)?'✓':'○'} ${name}<small>${desc}</small></div>`).join('')}</div></div>`);}

function startTraining(kind){if(working||battle)return;if(state.energy<18){toast('Сначала восстанови энергию.',true);return;}const e=exercises[kind];if(!e)return;working=true;let count=0,sum=0,repStart=performance.now(),raf=0,stopped=false;const duration=2300,total=6;modal(`<div class="dialog-body">${modalTop('ТРЕНИРОВКА · −18 ЭНЕРГИИ')}<h2 id="dialog-title">${e.call}</h2><p class="dialog-copy">${e.cue} Шесть повторений. Один шаг к легенде.</p><div class="workout-stage">${kind==='technique'?`<img class="workout-photo" src="${heroPath(state)}" alt="Твой спортсмен тренируется">`:`<div class="workout-photo workout-sprite" id="workout-sprite" role="img" aria-label="${kind==='strength'?'Анимация жима штанги':'Анимация становой тяги'}" style="background-position:0% ${kind==='strength'?'0%':'100%'}"></div>`}<div><div class="rep-count"><span id="rep-number">1</span><small> / 6</small></div><span class="tiny-label">ПОВТОРЕНИЕ</span><div class="timing-track" aria-label="Лови маркер в центральной зелёной зоне"><div class="timing-zone"></div><i class="timing-marker" id="rep-marker"></i></div><div class="timing-result" id="rep-result">Лови момент.</div><button class="primary-button" id="rep-button">${kind==='strength'?'ЖМИ!':kind==='technique'?'ЛОВИ!':'ПРИСЕДАЙ!'} <span>SPACE</span></button><div class="workout-score" id="rep-score">${Array(total).fill('<i></i>').join('')}</div><p class="training-instructions" style="margin-top:13px">Кнопка или пробел · зелёная зона = больше роста</p></div></div></div>`,'training');document.querySelector('.arena-scene').classList.add('scene-training');
const progress=()=>Math.min(1,(performance.now()-repStart)/duration);let pressed=false;
const hit=()=>{if(stopped||pressed)return;pressed=true;const p=progress(),quality=Math.max(0,1-Math.abs(p-.5)*2);sum+=quality;const dot=$('rep-score')?.children[count];if(dot)dot.className=quality>=.65?'hit':'miss';const out=$('rep-result');if(out)out.textContent=quality>=.86?'ЧИСТО! БАТЯ ГОРДИТСЯ.':quality>=.6?'Хороший повтор.':'Засчитано. Но можешь лучше.';$('rep-button').disabled=true;tone(quality>=.86?'perfect':'hit');};
const finish=()=>{stopped=true;cancelAnimationFrame(raf);const result=train(state,kind,sum/total);cleanup=null;document.removeEventListener('keydown',onKey);modalKind=null;closeModal();if(apply(result)){gainsPop(result.gains);tone('win');if(state.workouts%7===0)setTimeout(()=>toast(coachLines[Math.floor(state.workouts/7)%coachLines.length]),1600);}};
const frame=()=>{if(stopped)return;const p=progress();const marker=$('rep-marker');if(marker)marker.style.left=`${p*100}%`;const sprite=$('workout-sprite');if(sprite)sprite.style.backgroundPosition=`${p>.45&&p<.85?'100%':'0%'} ${kind==='strength'?'0%':'100%'}`;if(p>=1){if(!pressed){const dot=$('rep-score')?.children[count];if(dot)dot.className='miss';}count++;if(count===total){finish();return;}repStart=performance.now();pressed=false;$('rep-number').textContent=count+1;$('rep-button').disabled=false;$('rep-result').textContent='Следующий повтор. Держи ритм.';}raf=requestAnimationFrame(frame);};
const onKey=ev=>{if(ev.code==='Space'&&modalKind==='training'){ev.preventDefault();if(!ev.repeat)hit();}};document.addEventListener('keydown',onKey);$('rep-button').onclick=hit;cleanup=()=>{stopped=true;cancelAnimationFrame(raf);document.removeEventListener('keydown',onKey);};raf=requestAnimationFrame(frame);}

function timedAction(kind){if(working||battle)return;if(kind==='rest'&&state.energy===100){toast('Ты уже полон сил.');return;}if(kind==='work'&&state.energy<12){toast('Сначала передохни: для работы нужно 12 энергии.',true);return;}working=true;const seconds=kind==='rest'?6:8;const lines=kind==='rest'?['Сел на скамью. Выглядишь занятой.','Глубокий вдох. Неглубокие мысли.','Силы возвращаются. Понты тоже.']:['Переносишь блины. Не те, что со сметаной.','Сорок килограммов чужих амбиций.','Тренер готовит наличку. Без премии.'];modal(`<div class="dialog-body">${modalTop(kind==='rest'?'ВОССТАНОВЛЕНИЕ':'ПОДРАБОТКА')}<h2 id="dialog-title">${kind==='rest'?'ПОСИДИ КРАСИВО.':'ЖЕЛЕЗО ЛЮБИТ ПОРЯДОК.'}</h2><p class="work-description" id="work-description">${lines[0]}</p><div class="timer-ring"><i id="work-progress"></i></div><p class="dialog-copy">${kind==='rest'?'+40 энергии · бесплатно':`+${35+state.gym*15} ₽ · −12 энергии`} <span id="work-timer">${seconds} сек.</span></p></div>`,'timed');const started=performance.now();let raf=0,stop=false;const frame=()=>{if(stop)return;const p=Math.min(1,(performance.now()-started)/(seconds*1000));$('work-progress').style.width=`${p*100}%`;$('work-timer').textContent=`${Math.ceil(seconds*(1-p))} сек.`;$('work-description').textContent=lines[Math.min(2,Math.floor(p*3))];if(p===1){cleanup=null;closeModal();apply(kind==='rest'?rest(state):work(state));tone('tap');return;}raf=requestAnimationFrame(frame);};cleanup=()=>{stop=true;cancelAnimationFrame(raf);};raf=requestAnimationFrame(frame);}

const moveInfo={push:{name:'Натиск',tip:'Пробивает захват',tell:'опускает плечо и идёт вперёд',response:'Контрприём'},counter:{name:'Контрприём',tip:'Останавливает натиск',tell:'переносит вес назад и ждёт твоего рывка',response:'Захват'},grip:{name:'Захват',tip:'Ломает контрприём',tell:'тянет руки к твоему корпусу',response:'Натиск'}};
function startFight(){if(working||battle)return;const result=beginFight(state);if(result.error){toast(result.error,true);return;}battle=result.battle;state=result.state;persist();render();roundLock=false;fightView();tone('hit');}
function fightLogMarkup(current,message=''){
  const last=current.history.at(-1);
  if(!last)return `<div class="fight-log-placeholder">${esc(message||'Выбирай ответный приём и лови момент на шкале.')}</div>`;
  const beats={push:'grip',counter:'push',grip:'counter'};
  const outcome=last.move==='breathe'?'Перевёл дух':beats[last.move]===last.telegraph?'Приём удался':beats[last.telegraph]===last.move?'Соперник перехватил':'Лоб в лоб';
  const damage=value=>Math.max(0,Math.min(100,Number.isFinite(value)?Math.round(value):0));
  const dealt=damage(last.playerDamage),received=damage(last.enemyDamage);
  const move=last.move==='breathe'?'Восстановление':moveInfo[last.move]?.name||'Приём';
  return `<div class="fight-log-summary"><span>РАУНД ${damage(last.round)} · ${move}</span><strong>${outcome}</strong></div><div class="fight-log-stats"><div class="fight-log-stat dealt"><span>СОПЕРНИК ПОТЕРЯЛ</span><strong>${dealt?'−':''}${dealt}</strong><small>здоровья</small></div><div class="fight-log-stat received"><span>ТЫ ПОТЕРЯЛ</span><strong>${received?'−':''}${received}</strong><small>здоровья</small></div></div>${last.move==='breathe'?'<div class="fight-log-note">Запас сил восстановлен.</div>':''}`;
}
function fightView(message=''){if(!battle)return;const r=RIVALS.find(x=>x.id===battle.rivalId),tell=moveInfo[battle.telegraph];modal(`<div class="dialog-body">${modalTop(`КОВЁР · РАУНД ${Math.min(10,battle.round+1)} / 10`,false)}<h2 id="dialog-title">${esc(r.name.toUpperCase())}</h2><p class="muted">«${esc(r.quote)}»</p><div class="fight-stage"><div><div class="fighter-image" id="player-fighter" style="background-image:url('${heroPath(state)}')"><span>ТЫ · ${Math.round(battle.playerPower)} МОЩИ</span></div><div class="hp-label"><span>ЗДОРОВЬЕ</span><strong>${battle.playerHp} / 100</strong></div><div class="hp-track"><i style="width:${battle.playerHp}%"></i></div></div><span class="vs">VS</span><div><div class="fighter-image enemy" id="enemy-fighter" style="background-image:url('./assets/rivals.png');background-position:${position(r.portrait)}"><span>${esc(r.name)}</span></div><div class="hp-label"><span>ЗДОРОВЬЕ СОПЕРНИКА</span><strong>${battle.enemyHp} / 100</strong></div><div class="hp-track enemy-bar"><i style="width:${battle.enemyHp}%"></i></div></div></div><div class="telegraph"><strong>ЧИТАЙ ДВИЖЕНИЕ:</strong> соперник ${tell.tell}.<br>${state.wins<3?`Тренер шепчет: «${tell.response}, брат. И в ритм!»`:`Следующий приём: <strong>${tell.name}</strong>`}</div><div class="stamina-meter" role="progressbar" aria-label="Запас сил" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${battle.playerStamina}"><div class="stamina-label"><span>ЗАПАС СИЛ</span><strong>${battle.playerStamina} / 100</strong></div><div class="stamina-track ${battle.playerStamina<25?'low':''}"><i style="width:${battle.playerStamina}%"></i></div></div><div class="timing-caption">ПОПАДИ В ЗЕЛЁНУЮ ЗОНУ</div><div class="timing-track" style="height:20px;margin:10px 0 15px"><div class="timing-zone"></div><i class="timing-marker" id="fight-marker"></i></div><div class="move-buttons">${Object.entries(moveInfo).map(([id,m])=>`<button class="move-button" data-move="${id}" ${roundLock?'disabled':''}><strong>${m.name}</strong><small>${m.tip} · −14 сил</small></button>`).join('')}</div><button class="breathe-button" data-move="breathe" ${roundLock?'disabled':''}>ПЕРЕВЕСТИ ДУХ · +32 СИЛ · соперник продолжает атаковать</button><div class="fight-log" id="fight-log" aria-live="polite">${fightLogMarkup(battle,message)}</div><div class="battle-hint">${battle.playerStamina<14?'Сил почти нет — приёмы слабее. Можно перевести дух.':'Контрприём → натиск → захват → контрприём. На 10-м раунде побеждает тот, у кого больше здоровья.'}</div><button class="text-button" id="surrender-button" style="margin-top:15px">Сдаться и вернуться к железу</button></div>`,'fight');const started=performance.now();let stop=false;const frame=()=>{if(stop)return;const marker=$('fight-marker');if(marker)marker.style.left=`${(Math.sin((performance.now()-started)/650)+1)*50}%`;tickFrame=requestAnimationFrame(frame);};cleanup=()=>{stop=true;cancelAnimationFrame(tickFrame);};tickFrame=requestAnimationFrame(frame);}
function makeMove(move){if(!battle||battle.finished||roundLock)return;const timing=Number.parseFloat($('fight-marker')?.style.left||'50')/100,oldGym=state.gym,r=RIVALS.find(x=>x.id===battle.rivalId),result=fightTurn(state,battle,move,timing);if(result.error){toast(result.error,true);return;}roundLock=true;battle=result.battle;state=result.state;persist();document.querySelectorAll('[data-move]').forEach(b=>b.disabled=true);$('enemy-fighter')?.classList.add('hit-flash');$('player-fighter')?.classList.add('hit-flash');$('fight-log').innerHTML=fightLogMarkup(battle,result.message);tone('hit');setTimeout(()=>{roundLock=false;if(battle?.finished){const win=battle.result==='win';battle=null;persist();render();showFightResult(win,r,oldGym,result.message);}else if(battle)fightView(result.message);},950);}
function showFightResult(win,r,oldGym,message){if(state.won){showVictory();return;}modal(`<div class="dialog-body">${modalTop(win?'АВТОРИТЕТ ПОЛУЧЕН':'ПРОСТО РАЗМИНКА',false)}<h2 id="dialog-title" class="victory-heading" style="color:${win?'var(--gold)':'var(--muted)'}">${win?'ТВОЯ ВЗЯЛА.':'ЕЩЁ ВСТРЕТИМСЯ.'}</h2><p class="dialog-copy" style="text-align:center">${esc(win?r.winQuote:'Тебя положили на лопатки. Самооценку поднимешь жимом.')}<br>${esc(message)}</p>${win?`<div class="result-stats"><div><strong>+${r.reward} ₽</strong><span>в кассу</span></div><div><strong>${state.wins} / 12</strong><span>соперников позади</span></div><div><strong>${power(state)}</strong><span>твоя мощь</span></div></div>`:''}${state.gym>oldGym?`<div class="gym-panorama travel-panorama" style="background-position:${position(state.gym)}"></div><div class="telegraph"><strong>НОВЫЙ ЗАЛ: ${esc(GYMS[state.gym].name.toUpperCase())}</strong><br>${esc(GYMS[state.gym].description)}</div>`:''}<button class="primary-button" data-close>${win?'ДАЛЬШЕ — БОЛЬШЕ':'ПОЙДУ ПОДКАЧАЮСЬ'} <span>↗</span></button></div>`,'result');if(win){tone('win');confetti(28);}}
function showVictory(){modal(`<div class="dialog-body">${modalTop('ВСЕ 12 СОПЕРНИКОВ ПОБЕЖДЕНЫ')}<h2 id="dialog-title" class="victory-heading">BOSS OF THIS GYM.</h2><img class="victory-photo" src="./assets/hero-3.png?v=fullbody" alt="Ты стал огромным чемпионом качалки"><p class="dialog-copy" style="text-align:center">Ты пришёл сюда мешать воздух. Теперь воздух спрашивает у тебя разрешения.<br><strong>Гигабатя отдаёт тебе трон. И ключ от раздевалки.</strong></p><div class="result-stats"><div><strong>${state.workouts}</strong><span>подходов</span></div><div><strong>${Math.max(1,Math.round(state.playSeconds/60))} мин</strong><span>до легенды</span></div><div><strong>${state.respect}</strong><span>уважения</span></div></div><button class="primary-button" data-close>ОСТАТЬСЯ В СВОЁМ ЗАЛЕ <span>♛</span></button><p class="muted" style="text-align:center;margin-top:16px">Блины после себя всё равно убери.</p></div>`,'victory');tone('win');confetti(70);}
function confetti(count){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<count;i++){const el=document.createElement('i');el.className='celebration-spark';el.style.left=`${Math.random()*100}%`;el.style.background=['#ff653b','#8ddbcc','#e4b56d','#f0f1e8'][i%4];el.style.animationDelay=`${Math.random()*.6}s`;el.style.setProperty('--drift',`${(Math.random()-.5)*260}px`);document.body.append(el);setTimeout(()=>el.remove(),3600);}}
function resetPrompt(){modal(`<div class="dialog-body">${modalTop('СНОВА В ПОДВАЛ')}<h2 id="dialog-title">СБРОСИТЬ ВЕСЬ ПРОГРЕСС?</h2><p class="dialog-copy">Победы, мышцы и покупки исчезнут. Снова останутся только шорты и надежда.</p><div class="dialog-actions"><button class="secondary-button" data-close>Сохранить мышцы</button><button class="primary-button" id="confirm-reset">НАЧАТЬ ЗАНОВО</button></div></div>`);}

document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-close')){closeModal();return;}if(b.dataset.tab){tab=b.dataset.tab;render();tone();return;}if(b.dataset.train){startTraining(b.dataset.train);return;}if(b.dataset.buy){if(apply(buy(state,b.dataset.buy)))tone('perfect');return;}if(b.dataset.move){makeMove(b.dataset.move);return;}switch(b.id){case'rest-button':timedAction('rest');break;case'work-button':timedAction('work');break;case'fight-button':startFight();break;case'victory-button':showVictory();break;case'help-button':help();break;case'achievements-button':showAchievements();break;case'sound-toggle':sound=!sound;persist();render();tone('perfect');break;case'reset-button':resetPrompt();break;case'confirm-reset':cleanup?.();battle=null;state=createState();tab='gym';modalKind=null;closeModal();persist();render();toast('Новая жизнь. Старые шорты. Погнали.');break;case'surrender-button':if(roundLock)return;state={...state,energy:Math.max(20,state.energy-(battle?.serum?15:0))};battle=null;modalKind=null;closeModal();persist();render();toast('Сегодня железо полезнее ковра. Возвращайся сильнее.');break;}});
$('game-dialog').addEventListener('cancel',ev=>{ev.preventDefault();closeModal();});
document.querySelector('.tabbar').addEventListener('keydown',ev=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(ev.key))return;ev.preventDefault();const tabs=['gym','fight','shop','road'];let i=tabs.indexOf(tab);i=ev.key==='Home'?0:ev.key==='End'?3:(i+(ev.key==='ArrowRight'?1:3))%4;tab=tabs[i];render();$(`tab-${tab}`).focus();});
let lastTick=Date.now();setInterval(()=>{const now=Date.now();if(!document.hidden&&!state.won){state={...state,playSeconds:state.playSeconds+Math.min(10,Math.round((now-lastTick)/1000))};persist();}lastTick=now;},5000);
document.addEventListener('visibilitychange',()=>{lastTick=Date.now();persist();});window.addEventListener('pagehide',persist);
render();persist();if(battle)fightView('Схватка продолжается. Соперник дождался.');else if(!saved)setTimeout(()=>toast('Начни с жима лёжа. Лови зелёную зону — и расти.'),900);
setTimeout(()=>{const img=new Image();img.src=`./assets/hero-${Math.min(3,heroStage(state)+1)}.png?v=fullbody`;},2500);

const context=document.modelContext;
if(context?.registerTool){const controller=new AbortController();const tools=[{name:'get_gym_progress',title:'Прогресс в GYM BOSS',description:'Read the current character stats, resources, next opponent and campaign progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async input=>{if(input&&Object.keys(input).length)throw new Error('No arguments expected');return {gym:GYMS[state.gym].name,wins:state.wins,power:power(state),energy:state.energy,money:state.money,stats:Object.fromEntries(Object.keys(stats).map(k=>[k,state[k]])),nextRival:nextRival(state)?.name??null,won:state.won};}},{name:'open_gym_section',title:'Открыть раздел игры',description:'Open training, wrestling, equipment shop or opponent progression without completing an action.',inputSchema:{type:'object',properties:{section:{type:'string',enum:['gym','fight','shop','road']}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||Object.keys(input).some(k=>k!=='section')||!['gym','fight','shop','road'].includes(input.section))throw new Error('Expected section: gym, fight, shop, or road');if(modalKind)throw new Error('Close the current activity first');tab=input.section;render();return {section:tab};}}];for(const tool of tools){try{void Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
